var findTargetSumWays = function(nums, target) {
    const n = nums.length;
    const dp = Array(n + 1).fill(0).map(() => new Map());
    dp[0].set(0, 1);

    for (let i = 0; i < n; i++) {
        for (const [total, count] of dp[i]) {
            dp[i + 1].set(total + nums[i], 
                (dp[i + 1].get(total + nums[i]) || 0) + count);
            dp[i + 1].set(total - nums[i], 
                (dp[i + 1].get(total - nums[i]) || 0) + count);
        }
    }

    return dp[n].get(target) || 0;
};

